namespace StarlightSyndicateDemo;
public sealed partial class StateQ {public bool AdvancedEconomy{get;set;}public DateTime EconomyNext{get;set;}public List<NpcJobQ> NpcJobs{get;set;}=[];public List<ShortageQ> Shortages{get;set;}=[];public decimal NpcIndustrySinks{get;set;}}
public sealed class NpcJobQ {public string Id{get;set;}=Guid.NewGuid().ToString("N");public string Business{get;set;}="";public string Product{get;set;}="";public string State{get;set;}="Active";public DateTime Finish{get;set;}public Dictionary<string,decimal> Inputs{get;set;}=[];public int Output{get;set;}public decimal Fee{get;set;}}
public sealed class ShortageQ {public string Business{get;set;}="";public string Item{get;set;}="";public decimal Need{get;set;}public string Cause{get;set;}="";public DateTime Observed{get;set;}public string Shipment{get;set;}="";}
public sealed partial class BusinessC {public int IndustrySkillQ{get;set;}=3;}
public sealed partial class DemoWorld {
 public void SetEconomyQ(bool enabled){SystemsQ.AdvancedEconomy=enabled;if(enabled)foreach(var p in Population.Pilots)p.CapsuleerQ=true;SystemsQ.EconomyNext=Now;LogQ("Finite NPC industrial policy / "+enabled);}
 public string SupportNpcFactoryQ(string id){var b=Population.Businesses.FirstOrDefault(b=>b.Id==id&&b.Station==StationKey44&&b.Kind=="Factory");if(b==null||!Docked||Balance<500||b.IndustrySkillQ>=5)return "Dock at a local factory with 500 CR for its next qualification.";WalletChange(-500,"NPC factory training contract");b.Wallet+=500;Population.ExternalNet+=500;b.IndustrySkillQ++;return "";}
 public string RequestNpcProductQ(string id,int type){var b=Population.Businesses.FirstOrDefault(b=>b.Id==id&&b.Kind=="Factory"&&b.Station==StationKey44);string item=CatalogQ.Item(type);if(b==null||!Docked||Balance<200||!CatalogQ.Data.Activities.Any(a=>a.Kind=="manufacturing"&&a.Outputs.Any(o=>o.Type==type)))return "Dock at a consenting local factory with 200 CR and a source product.";WalletChange(-200,"NPC manufacturing commission");b.Wallet+=200;Population.ExternalNet+=200;b.Product=item;LogQ("Finite NPC manufacturing commission / "+b.Id+" / "+item);return "";}
 public void TickEconomyQ(){if(!SystemsQ.AdvancedEconomy||!Population.Enabled)return;foreach(var p in Population.Pilots)p.CapsuleerQ=true;foreach(var j in SystemsQ.NpcJobs.Where(j=>j.State=="Active"&&j.Finish<=Now)){var b=Population.Businesses.FirstOrDefault(b=>b.Id==j.Business);if(b==null){j.State="Lost";continue;}b.Stock[j.Product]=b.Stock.GetValueOrDefault(j.Product)+j.Output;j.State="Delivered";Population.GoodsProduced+=j.Output;}
  if(SystemsQ.EconomyNext>Now)return;SystemsQ.EconomyNext=Now.AddMinutes(10);SystemsQ.Shortages.Clear();
  foreach(var b in Population.Businesses.Where(b=>b.Kind=="Refiner")){CancelBusinessOrdersC(b);if(b.Stock.GetValueOrDefault("ore")<100)continue;var ore=IndustryCatalog37.OreContents("ore")!;b.Stock["ore"]-=100;foreach(var i in ore.Materials)b.Stock[i.Key]=b.Stock.GetValueOrDefault(i.Key)+decimal.Floor(i.Value*.5m);Population.GoodsConsumed+=100;}
  foreach(var b in Population.Businesses.Where(b=>b.Kind=="Factory")){CancelBusinessOrdersC(b);if(SystemsQ.NpcJobs.Any(j=>j.Business==b.Id&&j.State=="Active"))continue;if(CatalogQ.Data.Activities.FirstOrDefault(a=>a.Kind=="manufacturing"&&a.Outputs.Any(o=>CatalogQ.Item(o.Type)==b.Product)) is not {} recipe){SystemsQ.Shortages.Add(new(){Business=b.Id,Item=b.Product,Cause="Source manufacturing recipe unavailable",Observed=Now});continue;}
   if(recipe.Skills.Any(s=>s.level>b.IndustrySkillQ)){SystemsQ.Shortages.Add(new(){Business=b.Id,Item=b.Product,Cause="Factory qualification below source skill requirement",Observed=Now});continue;}
   var materials=recipe.Inputs.ToDictionary(i=>CatalogQ.Item(i.Type),i=>(decimal)i.Quantity);var missing=materials.Where(i=>b.Stock.GetValueOrDefault(i.Key)<i.Value).ToArray();if(missing.Length>0){foreach(var need in missing){var report=new ShortageQ{Business=b.Id,Item=need.Key,Need=need.Value-b.Stock.GetValueOrDefault(need.Key),Observed=Now,Cause="Insufficient owned source inputs"};SystemsQ.Shortages.Add(report);
     // Public market orders are an observation route; private player inventory is never consulted.
     var seller=Population.Businesses.Where(s=>s.Id!=b.Id&&LocationRegion(s.Station)==LocationRegion(b.Station)&&MarketOrders.Any(o=>o.BusinessC==s.Id&&o.Item==need.Key&&o.Remaining>0&&!o.Buy)).FirstOrDefault(s=>s.Stock.GetValueOrDefault(need.Key)>0||MarketOrders.Any(o=>o.BusinessC==s.Id&&o.Item==need.Key&&o.Remaining>0));if(seller==null)continue;CancelBusinessOrdersC(seller);int qty=(int)Math.Min(1000,Math.Min(report.Need,seller.Stock.GetValueOrDefault(need.Key)));if(qty<=0)continue;var shipment=DispatchShipmentC(seller.Id,b.Id,need.Key,qty);if(shipment!=null){report.Shipment=shipment.Id;report.Cause="Paid shipment in transit";}}
    continue;}
   decimal fee=5;if(b.Wallet<fee){SystemsQ.Shortages.Add(new(){Business=b.Id,Item=b.Product,Need=fee-b.Wallet,Observed=Now,Cause="Installation wallet exhausted"});continue;}var job=new NpcJobQ{Business=b.Id,Product=b.Product,Finish=Now.AddSeconds(Math.Max(1,recipe.Seconds)*(1-.04*b.IndustrySkillQ)),Output=recipe.Outputs.First(o=>CatalogQ.Item(o.Type)==b.Product).Quantity,Fee=fee,Inputs=new(materials)};foreach(var i in job.Inputs)b.Stock[i.Key]-=i.Value;b.Wallet-=fee;Population.Sinks+=fee;SystemsQ.NpcIndustrySinks+=fee;SystemsQ.NpcJobs.Add(job);}
  foreach(var p in Population.Pilots.Where(p=>p.Role is "Scout" or "Miner"&&!p.Contracted&&p.Fit.Hull>0&&p.System==SystemId&&p.Grid==Grid)){foreach(var target in Targets.Where(t=>t.Id.StartsWith("q-field:")&&t.Alive&&Microsoft.Xna.Framework.Vector3.Distance(p.Position,t.Position)<p.Fit.Stat("maxTargetRange")))p.Knowledge[target.Id]=Now.AddSeconds(20);}
  foreach(var p in Population.Pilots.Where(p=>p.Role=="Miner"&&!p.Contracted&&p.Fit.Hull>0&&p.System==SystemId&&p.Grid==Grid)){var actor=Targets.FirstOrDefault(t=>t.Id==p.Id&&t.Alive);if(actor==null||actor.Cap<8)continue;if(p.Fit.UtilityFit!="miner"&&p.Cargo.GetValueOrDefault("miner")>=1){p.Cargo["miner"]--;p.Fit.UtilityFit="miner";}if(p.Fit.UtilityFit!="miner"&&!p.Fit.Utilities.Any(m=>m.Online&&!m.Burnt&&m.Definition?.Harvest==true))continue;var field=SystemsQ.Fields.FirstOrDefault(f=>f.System==SystemId&&f.Grid==SolarGridKey&&f.State=="Breached"&&p.Knowledge.GetValueOrDefault("q-field:"+f.Id)>=Now);if(field==null)continue;var rock=Targets.FirstOrDefault(t=>t.Id=="q-rock:"+field.Id);if(rock==null||Microsoft.Xna.Framework.Vector3.Distance(actor.Position,rock.Position)>p.Fit.Stat("miningRange"))continue;decimal q=Math.Min(field.Remaining,10);if(q<=0)continue;actor.Cap-=8;field.Remaining-=q;field.Harvested+=q;rock.Ore=(float)field.Remaining;var business=Population.Businesses.First(b=>b.Id==p.Company);business.Stock["e_prism"]=business.Stock.GetValueOrDefault("e_prism")+q;Population.OreExtracted+=(long)q;}
  if(SystemsQ.NpcJobs.Count>1000)SystemsQ.NpcJobs.RemoveAll(j=>j.State!="Active"&&j.Finish<Now.AddDays(-30));
 }
}
